#pragma once
#include "Wire.h"
template<>struct Wire<SF_POLICY>;
template<>struct Wire<SF_STATS>;
template<>struct Wire<SF_CONTROL>;
template<>struct Wire<SF_POLICY> {static Json Encode(const SF_POLICY& v){Json j=Json::object();j["Size"]=EncodeWire(v.Size);j["Version"]=EncodeWire(v.Version);j["Flags"]=EncodeWire(v.Flags);j["Every"]=EncodeWire(v.Every);j["FirstBlock"]=EncodeWire(v.FirstBlock);j["BlockCount"]=EncodeWire(v.BlockCount);j["Reserved"]=EncodeWire(v.Reserved);return j;}static void Decode(const Json& j,SF_POLICY& v){Require(j.is_object(),"Wire struct must be object");for(auto it=j.begin();it!=j.end();++it){if(it.key()=="Size")DecodeWire(it.value(),v.Size);else if(it.key()=="Version")DecodeWire(it.value(),v.Version);else if(it.key()=="Flags")DecodeWire(it.value(),v.Flags);else if(it.key()=="Every")DecodeWire(it.value(),v.Every);else if(it.key()=="FirstBlock")DecodeWire(it.value(),v.FirstBlock);else if(it.key()=="BlockCount")DecodeWire(it.value(),v.BlockCount);else if(it.key()=="Reserved")DecodeWire(it.value(),v.Reserved);else throw SdkError(87,"Unknown wire field: "+it.key());}}};
template<>struct Wire<SF_STATS> {static Json Encode(const SF_STATS& v){Json j=Json::object();j["Reads"]=EncodeWire(v.Reads);j["Writes"]=EncodeWire(v.Writes);j["ReadBytes"]=EncodeWire(v.ReadBytes);j["WriteBytes"]=EncodeWire(v.WriteBytes);j["Injected"]=EncodeWire(v.Injected);j["Rejected"]=EncodeWire(v.Rejected);j["Matching"]=EncodeWire(v.Matching);j["Resets"]=EncodeWire(v.Resets);j["LeaseRemaining100ns"]=EncodeWire(v.LeaseRemaining100ns);j["SectorBytes"]=EncodeWire(v.SectorBytes);j["SectorCount"]=EncodeWire(v.SectorCount);j["PolicyActive"]=EncodeWire(v.PolicyActive);j["Reserved"]=EncodeWire(v.Reserved);return j;}static void Decode(const Json& j,SF_STATS& v){Require(j.is_object(),"Wire struct must be object");for(auto it=j.begin();it!=j.end();++it){if(it.key()=="Reads")DecodeWire(it.value(),v.Reads);else if(it.key()=="Writes")DecodeWire(it.value(),v.Writes);else if(it.key()=="ReadBytes")DecodeWire(it.value(),v.ReadBytes);else if(it.key()=="WriteBytes")DecodeWire(it.value(),v.WriteBytes);else if(it.key()=="Injected")DecodeWire(it.value(),v.Injected);else if(it.key()=="Rejected")DecodeWire(it.value(),v.Rejected);else if(it.key()=="Matching")DecodeWire(it.value(),v.Matching);else if(it.key()=="Resets")DecodeWire(it.value(),v.Resets);else if(it.key()=="LeaseRemaining100ns")DecodeWire(it.value(),v.LeaseRemaining100ns);else if(it.key()=="SectorBytes")DecodeWire(it.value(),v.SectorBytes);else if(it.key()=="SectorCount")DecodeWire(it.value(),v.SectorCount);else if(it.key()=="PolicyActive")DecodeWire(it.value(),v.PolicyActive);else if(it.key()=="Reserved")DecodeWire(it.value(),v.Reserved);else throw SdkError(87,"Unknown wire field: "+it.key());}}};
template<>struct Wire<SF_CONTROL> {static Json Encode(const SF_CONTROL& v){Json j=Json::object();j["Size"]=EncodeWire(v.Size);j["Version"]=EncodeWire(v.Version);j["Operation"]=EncodeWire(v.Operation);j["Result"]=EncodeWire(v.Result);j["Generation"]=EncodeWire(v.Generation);j["Owner"]=EncodeWire(v.Owner);j["Policy"]=EncodeWire(v.Policy);j["Stats"]=EncodeWire(v.Stats);return j;}static void Decode(const Json& j,SF_CONTROL& v){Require(j.is_object(),"Wire struct must be object");for(auto it=j.begin();it!=j.end();++it){if(it.key()=="Size")DecodeWire(it.value(),v.Size);else if(it.key()=="Version")DecodeWire(it.value(),v.Version);else if(it.key()=="Operation")DecodeWire(it.value(),v.Operation);else if(it.key()=="Result")DecodeWire(it.value(),v.Result);else if(it.key()=="Generation")DecodeWire(it.value(),v.Generation);else if(it.key()=="Owner")DecodeWire(it.value(),v.Owner);else if(it.key()=="Policy")DecodeWire(it.value(),v.Policy);else if(it.key()=="Stats")DecodeWire(it.value(),v.Stats);else throw SdkError(87,"Unknown wire field: "+it.key());}}};
